func GenerateHostname(ip netip.Addr) (hostname string) {
	if !ip.IsValid() {
		// TODO(s.chzhen):  Get rid of it.
		panic("aghnet generate hostname: invalid ip")
	}

	ip = ip.Unmap()
	hostname = ip.StringExpanded()

	if ip.Is4() {
		return strings.ReplaceAll(hostname, ".", "-")
	}

	return strings.ReplaceAll(hostname, ":", "-")
}
